def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if n == k * x:
        return 1
    if k == 1:
        return 1
    if x == 1:
        return n
    # Dynamic programming approach
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i == j * x:
                dp[j][i] = 1
            else:
                for l in range(x, i):
                    if dp[j - 1][i - l] > 0:
                        dp[j][i] += dp[j - 1][i - l]
    return dp[k][n]

