    # Initialize a set to store the unique numbers
    unique_numbers = {n}

    # Iterate over the transformation rules
    for rule in rules:
        # Apply the transformation rule to all numbers in the set
        for num in list(unique_numbers):
            if rule[0] in str(num):
                # If the transformation rule applies, add the transformed number to the set
                unique_numbers.add(int(str(num).replace(str(rule[0]), str(rule[1]))))

    # Return the length of the set (i.e., the number of unique numbers)
    return len(unique_numbers)

